import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

function count(field, s, least) {
  if (!COUNT.test(s) || BigInt(s) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line[0] === '#') continue
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      if (d === 'bucket' || d === 'window') {
        const n = d === 'bucket' ? 5 : 4
        if (f.length !== n) throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        if (events.length) throw new Fail('declarations must come before the first event')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        let p
        if (d === 'bucket') {
          const capacity = count('capacity', f[2], 1)
          const refill = count('refill', f[3], 0)
          const per = count('per', f[4], 1)
          p = { type: 'bucket', capacity, refill, per }
        } else {
          p = { type: 'window', limit: count('limit', f[2], 0), span: count('span', f[3], 1) }
        }
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        p.name = f[1]
        p.state = new Map()
        policies.set(f[1], p)
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (events.length) throw new Fail('declarations must come before the first event')
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        const ps = []
        for (const n of f.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          ps.push(policies.get(n))
        }
        routes.set(f[1], ps)
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = count('tick', f[1], 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (last !== null && tick < last) throw new Fail(`tick ${tick} is before tick ${last}`)
        last = tick
        events.push({ tick, key: f[2] })
      } else throw new Fail(`unknown directive ${d}`)
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

function advance(p, key, tick) {
  let s = p.state.get(key)
  if (p.type === 'bucket') {
    const cap = p.capacity * p.per
    if (!s) { s = { num: cap, at: tick }; p.state.set(key, s) }
    s.num += p.refill * (tick - s.at)
    if (s.num > cap) s.num = cap
    s.at = tick
  } else {
    if (!s) { s = []; p.state.set(key, s) }
    const cut = tick - p.span
    while (s.length && s[0] <= cut) s.shift()
  }
  return s
}

let out
try {
  const { routes, events } = parse(readFileSync(0, 'utf8'))
  const lines = []
  const stats = new Map()
  let ta = 0, td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const pre of routes.keys()) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    const ps = best === null ? [] : routes.get(best)
    const states = ps.map((p) => advance(p, key, tick))
    let denied = null
    for (let i = 0; i < ps.length; i++) {
      const p = ps[i], s = states[i]
      const ok = p.type === 'bucket' ? s.num >= p.per : BigInt(s.length) < p.limit
      if (!ok) { denied = p; break }
    }
    if (!denied) {
      ps.forEach((p, i) => { if (p.type === 'bucket') states[i].num -= p.per; else states[i].push(tick) })
    }
    const st = stats.get(key) || { a: 0, d: 0 }
    stats.set(key, st)
    if (denied) { st.d++; td++ } else { st.a++; ta++ }
    lines.push(denied ? `${tick} ${key} deny ${denied.name}` : `${tick} ${key} allow`)
  }
  if (mode === 'replay') out = lines
  else {
    out = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)).map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
    out.push(`total allowed=${ta} denied=${td}`)
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
